const file = $binary.data;
const body = $json;
if (!file) throw new Error('No binary data received. Send the PDF as field name \'data\'.');
if (!body.candidate_id) throw new Error('Missing candidate_id in form body.');

return [{
  json: {
    candidate_id: body.candidate_id,
    job_id:       body.job_id ?? null,
    filename:     file.fileName ?? 'cv.pdf',
    mimeType:     file.mimeType ?? 'application/pdf',
  },
  binary: { data: file }
}];

const resumeText  = $json.resume_text ?? '';
const prevNode    = $('Extract File Info').item.json;

if (!resumeText || resumeText.trim().length < 50) {
  throw new Error('CV text extraction produced insufficient content. Check the PDF quality.');
}

const systemPrompt = `You are an expert HR data extractor. Extract structured candidate data from the CV text below.
Return ONLY valid JSON with exactly this schema — no prose, no markdown fences:
{
  "full_name":    "string",
  "email":        "string",
  "phone":        "string or null",
  "location":     "string or null",
  "linkedin_url": "string or null",
  "metadata": {
    "skills":           ["array of technology/skill strings"],
    "languages":        ["array of human language strings"],
    "certifications":   ["array of certification name strings"],
    "years_experience": 0
  }
}`;

return [{
  json: {
    candidate_id:  prevNode.candidate_id,
    job_id:        prevNode.job_id,
    filename:      prevNode.filename,
    mimeType:      prevNode.mimeType,
    resume_text:   resumeText,
    system_prompt: systemPrompt,
    user_prompt:   `CV Text:\n${resumeText.slice(0, 12000)}`,
  },
  binary: $binary
}];

