{
  "type": "object",
  "properties": {
    "full_name":    { "type": "string",  "description": "Full name of the candidate" },
    "email":        { "type": "string",  "description": "Primary email address" },
    "phone":        { "type": "string",  "description": "Phone number or null",  "nullable": true },
    "location":     { "type": "string",  "description": "City, Country or null",   "nullable": true },
    "linkedin_url": { "type": "string",  "description": "LinkedIn profile URL or null", "nullable": true },
    "metadata": {
      "type": "object",
      "properties": {
        "skills":           { "type": "array",  "items": { "type": "string" }, "description": "Technical and soft skills" },
        "languages":        { "type": "array",  "items": { "type": "string" }, "description": "Spoken languages" },
        "certifications":   { "type": "array",  "items": { "type": "string" }, "description": "Professional certifications" },
        "years_experience": { "type": "number", "description": "Total years of professional experience" }
      },
      "required": ["skills", "languages", "certifications", "years_experience"]
    }
  },
  "required": ["full_name", "email", "metadata"]
}

