// LLM Chain with Structured Output Parser returns parsed JSON directly in $json.output
let profile;
try {
  profile = typeof $json.output === 'string' ? JSON.parse($json.output) : $json.output;
} catch (e) {
  throw new Error(`Failed to parse LLM structured output: ${e.message}. Raw: ${JSON.stringify($json.output)}`);
}

if (!profile?.full_name || !profile?.email) {
  throw new Error(`LLM returned incomplete profile. Missing full_name or email. Got: ${JSON.stringify(profile)}`);
}

const prev        = $('Prepare LLM Prompt').item.json;
const resumeText  = prev.resume_text;

// Build rich text blob for embedding (respects text-embedding-004 token budget ~2048 tokens)
const textForEmbedding = [
  profile.full_name,
  profile.location,
  profile.metadata?.skills?.slice(0, 20).join(', '),
  profile.metadata?.certifications?.slice(0, 10).join(', '),
  profile.metadata?.languages?.join(', '),
  resumeText?.slice(0, 2500),
].filter(Boolean).join('\n');

return [{
  json: {
    candidate_id:       prev.candidate_id,
    job_id:             prev.job_id,
    filename:           prev.filename,
    mimeType:           prev.mimeType,
    resume_text:        resumeText,
    text_for_embedding: textForEmbedding,
    full_name:          profile.full_name,
    email:              profile.email,
    phone:              profile.phone       ?? null,
    location:           profile.location    ?? null,
    linkedin_url:       profile.linkedin_url ?? null,
    metadata:           profile.metadata,
  },
  binary: $('Prepare LLM Prompt').item.binary,
}];

// Gemini REST response: { embedding: { values: number[] } }
const values = $json.embedding?.values;

if (!Array.isArray(values)) {
  throw new Error(`Gemini embeddings API returned unexpected shape: ${JSON.stringify($json)}`);
}

if (values.length !== 768) {
  throw new Error(`Expected 768-dim vector from text-embedding-004, got ${values.length} dims.`);
}

const prev = $('Parse & Enrich Profile').item.json;

return [{
  json: {
    ...prev,
    embedding: values,
  },
  binary: $('Parse & Enrich Profile').item.binary,
}];

const prev        = $('Extract Embedding Vector').item.json;
const supabaseUrl = $env.SUPABASE_URL;
const resume_url  = `${supabaseUrl}/storage/v1/object/public/resumes/${prev.candidate_id}/${prev.filename}`;

return [{
  json: { ...prev, resume_url }
}];

const rawText = $json.candidates?.[0]?.content?.parts?.[0]?.text;
if (!rawText) throw new Error('Gemini fallback also failed to return a response.');

const profile = JSON.parse(rawText);
const prev    = $('Prepare LLM Prompt').item.json;
const resumeText = prev.resume_text;

const textForEmbedding = [
  profile.full_name,
  profile.location,
  profile.metadata?.skills?.slice(0, 20).join(', '),
  profile.metadata?.certifications?.slice(0, 10).join(', '),
  profile.metadata?.languages?.join(', '),
  resumeText?.slice(0, 2500),
].filter(Boolean).join('\n');

return [{
  json: {
    candidate_id:       prev.candidate_id,
    job_id:             prev.job_id,
    filename:           prev.filename,
    mimeType:           prev.mimeType,
    resume_text:        resumeText,
    text_for_embedding: textForEmbedding,
    full_name:          profile.full_name,
    email:              profile.email,
    phone:              profile.phone       ?? null,
    location:           profile.location    ?? null,
    linkedin_url:       profile.linkedin_url ?? null,
    metadata:           profile.metadata,
    llm_provider:      'gemini-fallback',
  },
  binary: $('Prepare LLM Prompt').item.binary,
}];
